class CollaborationManager:
    """Manages real-time collaboration state, including users, sessions, and conflict resolution."""

    def __init__(self):
        self.active_users: Dict[str, Dict] = {}  # user_id -> {last_seen, current_dataset_id, ...}
        self.shared_state: Dict[str, Any] = {}   # dataset_id -> current state snapshot
        self.lock = threading.RLock()
        self.history: List[AnalysisStep] = []
        self.annotations: Dict[str, List[Annotation]] = {}  # dataset_id -> [Annotation]

    def add_user(self, user_id: str, dataset_id: str = None):
        with self.lock:
            self.active_users[user_id] = {
                "last_seen": datetime.utcnow().isoformat(),
                "current_dataset_id": dataset_id
            }

    def remove_user(self, user_id: str):
        with self.lock:
            if user_id in self.active_users:
                del self.active_users[user_id]

    def update_user_activity(self, user_id: str, dataset_id: str = None):
        with self.lock:
            if user_id in self.active_users:
                self.active_users[user_id]["last_seen"] = datetime.utcnow().isoformat()
                if dataset_id:
                    self.active_users[user_id]["current_dataset_id"] = dataset_id

    def record_step(self, step: AnalysisStep):
        with self.lock:
            self.history.append(step)

    def get_history(self) -> List[AnalysisStep]:
        with self.lock:
            return list(self.history)

    def add_annotation(self, annotation: Annotation):
        with self.lock:
            if annotation.dataset_id not in self.annotations:
                self.annotations[annotation.dataset_id] = []
            self.annotations[annotation.dataset_id].append(annotation)

    def get_annotations(self, dataset_id: str) -> List[Annotation]:
        with self.lock:
            return list(self.annotations.get(dataset_id, []))


class VersionControl:
    """Manages versioning of datasets and analysis results."""

    def __init__(self):
        self.versions: Dict[str, List[Dict]] = {}  # dataset_id -> [{version_id, timestamp, snapshot, step_id}]
        self.current_state: Dict[str, Any] = {}  # dataset_id -> current snapshot

    def save_snapshot(self, dataset_id: str, step_id: str):
        """Save current state of dataset as a version."""
        if dataset_id not in self.current_state:
            return

        snapshot = copy.deepcopy(self.current_state[dataset_id])
        version_id = str(uuid.uuid4())

        if dataset_id not in self.versions:
            self.versions[dataset_id] = []

        self.versions[dataset_id].append({
            "version_id": version_id,
            "timestamp": datetime.utcnow().isoformat(),
            "snapshot": snapshot,
            "step_id": step_id
        })

    def get_version(self, dataset_id: str, version_id: str) -> Optional[Dict]:
        if dataset_id in self.versions:
            for v in self.versions[dataset_id]:
                if v["version_id"] == version_id:
                    return v["snapshot"]
        return None

    def get_all_versions(self, dataset_id: str) -> List[Dict]:
        return list(self.versions.get(dataset_id, []))


