class VersionControl:
    def __init__(self):
        self.versions: Dict[str, Dict[str, Any]] = {}  # dataset_id -> {version_hash: Dataset, ...}
        self.history: Dict[str, List[ChangeRecord]] = {}  # dataset_id -> list of ChangeRecord
        self.current_version: Dict[str, str] = {}  # dataset_id -> current_version_hash

    def _hash_dataframe(self, df: pd.DataFrame) -> str:
        # Deterministic hash for DataFrame content
        return hashlib.sha256(pd.util.hash_pandas_object(df, index=True).values).hexdigest()

    def create_version(self, dataset: Dataset) -> str:
        version_hash = self._hash_dataframe(dataset.data)
        if dataset.id not in self.versions:
            self.versions[dataset.id] = {}
        self.versions[dataset.id][version_hash] = dataset
        self.current_version[dataset.id] = version_hash
        return version_hash

    def get_current_dataset(self, dataset_id: str) -> Optional[Dataset]:
        if dataset_id not in self.current_version:
            return None
        version_hash = self.current_version[dataset_id]
        return self.versions[dataset_id].get(version_hash)

    def add_change_record(self, record: ChangeRecord):
        if record.dataset_id not in self.history:
            self.history[record.dataset_id] = []
        self.history[record.dataset_id].append(record)

    def get_history(self, dataset_id: str) -> List[ChangeRecord]:
        return self.history.get(dataset_id, [])

    def revert_to_version(self, dataset_id: str, target_version_hash: str) -> Optional[Dataset]:
        if dataset_id not in self.versions or target_version_hash not in self.versions[dataset_id]:
            return None
        self.current_version[dataset_id] = target_version_hash
        return self.versions[dataset_id][target_version_hash]

